import type { AgentComposerMessages, AgentComposerProps, AgentComposerSubmitValue } from '@components/agent-composer';
import type { AgentMessageMessages, AgentMessagePartRenderer, AgentMessageProps } from '@components/agent-message';
import type { MessageScrollerMessages } from '@components/message-scroller';
import type { ChatStatus, UIMessage } from 'ai';
import type { ComponentPropsWithRef, ReactNode } from 'react';

export type AgentChatMessages = {
	empty: string;
	errorLabel: string;
	pending?: string;
	retry: string;
	transcript: string;
};

export type ResolvedAgentChatMessages = AgentChatMessages & {
	pending: string;
};

export const defaultAgentChatMessages: ResolvedAgentChatMessages = {
	empty: '开始一段新对话',
	errorLabel: '对话出错',
	pending: '模型响应处理中',
	retry: '重试',
	transcript: '对话消息',
};

export type AgentChatMessageOverrides = Partial<AgentChatMessages> & {
	composer?: Partial<AgentComposerMessages>;
	message?: Partial<AgentMessageMessages>;
	scroller?: Partial<MessageScrollerMessages>;
};

export function resolveAgentChatMessages(messages?: AgentChatMessageOverrides): ResolvedAgentChatMessages {
	return { ...defaultAgentChatMessages, ...messages };
}

export type AgentChatRenderMessageContext = {
	defaultMessage: ReactNode;
	index: number;
	message: UIMessage;
};

export type AgentChatMessageRenderer = (context: AgentChatRenderMessageContext) => ReactNode | undefined;

export type AgentChatProps = Omit<ComponentPropsWithRef<'section'>, 'onError'> & {
	autoScroll?: boolean;
	composerProps?: Omit<
		AgentComposerProps,
		| 'error'
		| 'files'
		| 'messages'
		| 'model'
		| 'onFilesChange'
		| 'onStop'
		| 'onSubmit'
		| 'onValueChange'
		| 'status'
		| 'value'
	>;
	connection?: ReactNode;
	disabled?: boolean;
	emptyState?: ReactNode;
	error?: ReactNode;
	files: readonly File[];
	footer?: ReactNode;
	header?: ReactNode;
	messageProps?: Omit<AgentMessageProps, 'message' | 'messages' | 'renderPart' | 'renderTool'>;
	messages?: AgentChatMessageOverrides;
	model?: ReactNode;
	onFilesChange: (files: File[]) => void;
	onRetry?: () => void;
	onSend: (value: AgentComposerSubmitValue) => void;
	onStop?: () => void;
	onTextChange: (value: string) => void;
	renderMessage?: AgentChatMessageRenderer;
	renderPart?: AgentMessagePartRenderer;
	renderTool?: AgentMessagePartRenderer;
	status: ChatStatus;
	text: string;
	toolbar?: ReactNode;
	value: readonly UIMessage[];
};

import type { UIMessage } from 'ai';

export type AgentRuntimeMessageLimits = {
	maxArrayItems?: number;
	maxDataUrlBytes?: number;
	maxDepth?: number;
	maxMessages?: number;
	maxNodes?: number;
	maxObjectKeys?: number;
	maxParts?: number;
	maxStringBytes?: number;
};

export type AgentRuntimeMessageValidation =
	| { success: true; messages: readonly UIMessage[] }
	| { success: false; code: AgentRuntimeMessageErrorCode; message: string };
export type AgentRuntimeMessageErrorCode =
	| 'data-url-bytes'
	| 'depth'
	| 'invalid'
	| 'messages'
	| 'nodes'
	| 'parts'
	| 'string-bytes';

type ResolvedLimits = Required<AgentRuntimeMessageLimits>;
type InspectionState = {
	active: WeakSet<object>;
	dataUrlBytes: number;
	limits: ResolvedLimits;
	nodes: number;
	parts: number;
	stringBytes: number;
};

export const AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS: ResolvedLimits = {
	maxArrayItems: 512,
	maxDataUrlBytes: 32 * 1024 * 1024,
	maxDepth: 32,
	maxMessages: 100,
	maxNodes: 10_000,
	maxObjectKeys: 64,
	maxParts: 2_000,
	maxStringBytes: 2 * 1024 * 1024,
};

export function validateAgentRuntimeMessages(
	value: unknown,
	limits: AgentRuntimeMessageLimits = {},
): AgentRuntimeMessageValidation {
	const resolved = resolveLimits(limits);
	if (!Array.isArray(value)) return invalid('消息记录必须是数组。');
	const messageCount = safeArrayLength(value);
	if (messageCount === undefined) return invalid('消息记录无法安全读取。');
	if (messageCount > resolved.maxMessages) {
		return failure('messages', `消息数量不能超过 ${resolved.maxMessages} 条。`);
	}
	let parts = 0;
	for (let index = 0; index < messageCount; index += 1) {
		const message = readDataProperty(value, String(index));
		if (!isRecord(message)) return invalid(`第 ${index + 1} 条消息无效。`);
		const id = readDataProperty(message, 'id');
		const role = readDataProperty(message, 'role');
		const messageParts = readDataProperty(message, 'parts');
		if (typeof id !== 'string' || !id || (role !== 'assistant' && role !== 'system' && role !== 'user')) {
			return invalid(`第 ${index + 1} 条消息身份无效。`);
		}
		if (!Array.isArray(messageParts)) return invalid(`第 ${index + 1} 条消息内容必须是数组。`);
		const partCount = safeArrayLength(messageParts);
		if (partCount === undefined) return invalid(`第 ${index + 1} 条消息内容无法安全读取。`);
		parts += partCount;
		if (parts > resolved.maxParts) return failure('parts', `消息内容不能超过 ${resolved.maxParts} 个部分。`);
	}
	const state: InspectionState = {
		active: new WeakSet(),
		dataUrlBytes: 0,
		limits: resolved,
		nodes: 0,
		parts,
		stringBytes: 0,
	};
	const issue = inspectRuntimeValue(value, 0, state);
	return issue ?? { success: true, messages: value as readonly UIMessage[] };
}

export type AgentRuntimeValueMeasurement =
	| { success: true; dataUrlBytes: number; nodes: number; stringBytes: number }
	| Exclude<AgentRuntimeMessageValidation, { success: true }>;

export function measureAgentRuntimeValue(
	value: unknown,
	limits: AgentRuntimeMessageLimits = {},
): AgentRuntimeValueMeasurement {
	const resolved = resolveLimits(limits);
	const state: InspectionState = {
		active: new WeakSet(),
		dataUrlBytes: 0,
		limits: resolved,
		nodes: 0,
		parts: 0,
		stringBytes: 0,
	};
	const issue = inspectRuntimeValue(value, 0, state);
	return (
		issue ?? {
			success: true,
			dataUrlBytes: state.dataUrlBytes,
			nodes: state.nodes,
			stringBytes: state.stringBytes,
		}
	);
}

export function validateAgentRuntimeValue(
	value: unknown,
	limits: AgentRuntimeMessageLimits = {},
): Exclude<AgentRuntimeMessageValidation, { success: true }> | undefined {
	const result = measureAgentRuntimeValue(value, limits);
	return result.success ? undefined : result;
}

function inspectRuntimeValue(
	value: unknown,
	depth: number,
	state: InspectionState,
): Exclude<AgentRuntimeMessageValidation, { success: true }> | undefined {
	state.nodes += 1;
	if (state.nodes > state.limits.maxNodes) return failure('nodes', '消息结构过于复杂。');
	if (depth > state.limits.maxDepth) return failure('depth', '消息嵌套层级过深。');
	if (typeof value === 'string') return addStringBytes(value, state);
	if (value === undefined || value === null || typeof value === 'boolean' || typeof value === 'number')
		return undefined;
	if (typeof value !== 'object') return invalid('消息包含不受支持的运行时值。');
	if (state.active.has(value)) return invalid('消息不能包含循环引用。');
	state.active.add(value);
	try {
		if (Array.isArray(value)) {
			const length = safeArrayLength(value);
			if (length === undefined) return invalid('消息数组无法安全读取。');
			if (length > state.limits.maxArrayItems) return failure('nodes', '消息数组条目过多。');
			for (let index = 0; index < length; index += 1) {
				const descriptor = safeOwnDescriptor(value, String(index));
				if (!descriptor || !('value' in descriptor)) return invalid('消息数组包含不可读取的条目。');
				const issue = inspectRuntimeValue(descriptor.value, depth + 1, state);
				if (issue) return issue;
			}
			return undefined;
		}
		let inspected = 0;
		try {
			for (const key in value) {
				inspected += 1;
				if (inspected > state.limits.maxObjectKeys) return failure('nodes', '消息对象字段过多。');
				let own: boolean;
				try {
					own = Object.hasOwn(value, key);
				} catch {
					return invalid('消息对象无法安全读取。');
				}
				if (!own) continue;
				const keyIssue = addStringBytes(key, state);
				if (keyIssue) return keyIssue;
				const descriptor = safeOwnDescriptor(value, key);
				if (!descriptor || !('value' in descriptor)) return invalid('消息不能包含 getter 或不可读取字段。');
				const issue = inspectRuntimeValue(descriptor.value, depth + 1, state);
				if (issue) return issue;
			}
		} catch {
			return invalid('消息对象无法安全读取。');
		}
		return undefined;
	} finally {
		state.active.delete(value);
	}
}

function addStringBytes(
	value: string,
	state: InspectionState,
): Exclude<AgentRuntimeMessageValidation, { success: true }> | undefined {
	const dataUrl = value.startsWith('data:');
	const current = dataUrl ? state.dataUrlBytes : state.stringBytes;
	const maximum = dataUrl ? state.limits.maxDataUrlBytes : state.limits.maxStringBytes;
	const bytes = boundedUtf8ByteLength(value, maximum - current);
	if (bytes === undefined) {
		return dataUrl
			? failure('data-url-bytes', '消息中的 Data URL 总大小超过限制。')
			: failure('string-bytes', '消息文本总大小超过限制。');
	}
	if (dataUrl) state.dataUrlBytes += bytes;
	else state.stringBytes += bytes;
	return undefined;
}

function boundedUtf8ByteLength(value: string, remaining: number): number | undefined {
	if (remaining < 0 || value.length > remaining) return undefined;
	let bytes = 0;
	for (let index = 0; index < value.length; index += 1) {
		const code = value.charCodeAt(index);
		if (code < 0x80) bytes += 1;
		else if (code < 0x800) bytes += 2;
		else if (code >= 0xd800 && code <= 0xdbff && index + 1 < value.length) {
			const next = value.charCodeAt(index + 1);
			if (next >= 0xdc00 && next <= 0xdfff) {
				bytes += 4;
				index += 1;
			} else bytes += 3;
		} else bytes += 3;
		if (bytes > remaining) return undefined;
	}
	return bytes;
}

function readDataProperty(value: object, key: PropertyKey): unknown {
	const descriptor = safeOwnDescriptor(value, key);
	return descriptor && 'value' in descriptor ? descriptor.value : undefined;
}

function safeArrayLength(value: unknown[]): number | undefined {
	const descriptor = safeOwnDescriptor(value, 'length');
	return descriptor && 'value' in descriptor && typeof descriptor.value === 'number'
		? Math.max(0, Math.floor(descriptor.value))
		: undefined;
}

function safeOwnDescriptor(value: object, key: PropertyKey): PropertyDescriptor | undefined {
	try {
		return Object.getOwnPropertyDescriptor(value, key);
	} catch {
		return undefined;
	}
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null;
}

function resolveLimits(limits: AgentRuntimeMessageLimits): ResolvedLimits {
	return {
		maxArrayItems: resolveLimit(limits.maxArrayItems, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxArrayItems),
		maxDataUrlBytes: resolveLimit(limits.maxDataUrlBytes, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxDataUrlBytes),
		maxDepth: resolveLimit(limits.maxDepth, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxDepth),
		maxMessages: resolveLimit(limits.maxMessages, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxMessages),
		maxNodes: resolveLimit(limits.maxNodes, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxNodes),
		maxObjectKeys: resolveLimit(limits.maxObjectKeys, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxObjectKeys),
		maxParts: resolveLimit(limits.maxParts, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxParts),
		maxStringBytes: resolveLimit(limits.maxStringBytes, AGENT_RUNTIME_DEFAULT_MESSAGE_LIMITS.maxStringBytes),
	};
}

function resolveLimit(value: number | undefined, fallback: number): number {
	return value === undefined || !Number.isFinite(value) ? fallback : Math.max(0, Math.floor(value));
}

function invalid(message: string): Exclude<AgentRuntimeMessageValidation, { success: true }> {
	return failure('invalid', message);
}

function failure(
	code: AgentRuntimeMessageErrorCode,
	message: string,
): Exclude<AgentRuntimeMessageValidation, { success: true }> {
	return { success: false, code, message };
}

'use client';

import { AgentComposer, type AgentComposerStatus } from '@components/agent-composer';
import { AgentMessage } from '@components/agent-message';
import {
	MessageScroller,
	MessageScrollerButton,
	MessageScrollerContent,
	MessageScrollerItem,
	MessageScrollerProvider,
	MessageScrollerViewport,
} from '@components/message-scroller';
import { LoaderCircle, RotateCcw } from 'lucide-react';
import { type ReactNode, useEffect, useState } from 'react';
import { cn } from '@/lib/utils';
import type { AgentChatProps } from './agent-chat-types';
import { resolveAgentChatMessages } from './agent-chat-types';
import { validateAgentRuntimeMessages } from './runtime-message-validation';

export function AgentChat({
	autoScroll = true,
	className,
	composerProps,
	connection,
	disabled = false,
	emptyState,
	error,
	files,
	footer,
	header,
	messageProps,
	messages,
	model,
	onFilesChange,
	onRetry,
	onSend,
	onStop,
	onTextChange,
	renderMessage,
	renderPart,
	renderTool,
	status,
	text,
	toolbar,
	value,
	...props
}: AgentChatProps) {
	const copy = resolveAgentChatMessages(messages);
	const messageValidation = validateAgentRuntimeMessages(value);
	const visibleMessages = messageValidation.success ? messageValidation.messages : [];
	const messageError = messageValidation.success ? undefined : messageValidation.message;
	const effectiveDisabled = disabled || !messageValidation.success;
	const visibleError = messageError ?? error;
	const hasHeader = header !== undefined || connection !== undefined || toolbar !== undefined;
	const busy = status === 'submitted' || status === 'streaming';
	const showActivity = status === 'submitted' || (status === 'streaming' && !hasAssistantProgress(visibleMessages));
	return (
		<section
			data-slot='agent-chat'
			data-status={status}
			data-invalid-messages={messageError ? 'true' : 'false'}
			aria-busy={busy || undefined}
			className={cn(
				'border-border bg-background text-foreground flex size-full min-h-0 min-w-0 flex-col overflow-hidden rounded-md border',
				className,
			)}
			{...props}
		>
			{hasHeader ? (
				<header
					data-slot='agent-chat-header'
					className='border-border flex min-h-12 min-w-0 flex-wrap items-center gap-2 border-b px-3 py-2'
				>
					<div className='min-w-0 flex-1'>{header}</div>
					{connection !== undefined ? <div className='shrink-0'>{connection}</div> : null}
					{toolbar !== undefined ? <div className='flex shrink-0 items-center gap-1'>{toolbar}</div> : null}
				</header>
			) : null}
			<div className='relative min-h-0 flex-1'>
				<MessageScrollerProvider autoScroll={autoScroll} defaultScrollPosition='last-anchor'>
					<MessageScroller>
						<MessageScrollerViewport messages={messages?.scroller} aria-label={copy.transcript}>
							<MessageScrollerContent className='gap-5 px-3 py-5 md:px-6'>
								{visibleMessages.length === 0 && !showActivity ? (
									<div
										data-slot='agent-chat-empty'
										className='text-muted-foreground flex min-h-[16rem] flex-1 items-center justify-center px-4 text-center text-sm'
									>
										{emptyState ?? copy.empty}
									</div>
								) : (
									visibleMessages.map((message, index) => {
										const defaultMessage = (
											<AgentMessage
												{...messageProps}
												message={message}
												messages={messages?.message}
												renderPart={renderPart}
												renderTool={renderTool}
											/>
										);
										return (
											<MessageScrollerItem
												key={message.id}
												messageId={message.id}
												scrollAnchor={message.role === 'user'}
											>
												{resolveRenderedMessage(renderMessage?.({ defaultMessage, index, message }), defaultMessage)}
											</MessageScrollerItem>
										);
									})
								)}
								{showActivity ? <AgentChatActivity label={copy.pending} /> : null}
							</MessageScrollerContent>
						</MessageScrollerViewport>
						<MessageScrollerButton messages={messages?.scroller} />
					</MessageScroller>
				</MessageScrollerProvider>
			</div>
			<div data-slot='agent-chat-composer-region' className='border-border shrink-0 border-t p-2 md:p-3'>
				{visibleError !== undefined ? (
					<div
						role='alert'
						aria-label={copy.errorLabel}
						className='text-error mb-2 flex min-w-0 items-center gap-2 px-1 text-sm'
					>
						<div className='min-w-0 flex-1 break-words'>{visibleError}</div>
						{onRetry ? (
							<button
								type='button'
								className='btn btn-ghost btn-sm shrink-0'
								disabled={effectiveDisabled || busy}
								onClick={onRetry}
							>
								<RotateCcw aria-hidden='true' className='size-4' />
								{copy.retry}
							</button>
						) : null}
					</div>
				) : null}
				<AgentComposer
					{...composerProps}
					disabled={effectiveDisabled}
					files={files}
					messages={messages?.composer}
					model={model}
					onFilesChange={onFilesChange}
					onStop={onStop}
					onSubmit={onSend}
					onValueChange={onTextChange}
					status={toComposerStatus(status)}
					value={text}
				/>
				{footer !== undefined ? (
					<footer data-slot='agent-chat-footer' className='text-muted-foreground px-1 pt-2 text-xs'>
						{footer}
					</footer>
				) : null}
			</div>
		</section>
	);
}

function resolveRenderedMessage(rendered: ReactNode | undefined, fallback: ReactNode) {
	return rendered === undefined ? fallback : rendered;
}

function toComposerStatus(status: AgentChatProps['status']): AgentComposerStatus {
	if (status === 'submitted') return 'submitting';
	return status;
}

function AgentChatActivity({ label }: { label: string }) {
	const [elapsed, setElapsed] = useState(0);
	useEffect(() => {
		const startedAt = Date.now();
		const timer = window.setInterval(() => setElapsed(Date.now() - startedAt), 100);
		return () => window.clearInterval(timer);
	}, []);
	return (
		<div
			data-slot='agent-chat-pending'
			role='status'
			aria-label={label}
			aria-live='polite'
			className='text-muted-foreground flex min-h-8 items-center gap-2 text-xs tabular-nums'
		>
			<LoaderCircle aria-hidden='true' className='size-4 shrink-0 animate-spin' />
			<span aria-hidden='true'>{formatAgentChatElapsed(elapsed)}</span>
		</div>
	);
}

export function formatAgentChatElapsed(elapsedMilliseconds: number): string {
	const bounded = Math.max(0, Number.isFinite(elapsedMilliseconds) ? elapsedMilliseconds : 0);
	if (bounded < 60_000) return `${(bounded / 1_000).toFixed(1)}s`;
	const totalSeconds = Math.floor(bounded / 1_000);
	const minutes = Math.floor(totalSeconds / 60);
	return `${minutes}:${String(totalSeconds % 60).padStart(2, '0')}`;
}

function hasAssistantProgress(messages: readonly import('ai').UIMessage[]): boolean {
	let lastUserIndex = -1;
	for (const [index, message] of messages.entries()) {
		if (message.role === 'user') lastUserIndex = index;
	}
	for (let index = lastUserIndex + 1; index < messages.length; index += 1) {
		const message = messages[index];
		if (message?.role !== 'assistant') continue;
		for (const part of message.parts) {
			if (part.type === 'step-start') continue;
			if (part.type === 'text' || part.type === 'reasoning') {
				if (part.text.length > 0) return true;
				continue;
			}
			return true;
		}
	}
	return false;
}

export type { AgentComposerSubmitValue } from '@components/agent-composer';
export * from './agent-chat';
export * from './agent-chat-types';
export * from './runtime-message-validation';
